#!/usr/bin/env python3
import sys, csv, io, gzip, base64, psycopg2

if len(sys.argv) < 2:
    print("Kullanim: python3 import_abone.py "<connection_string>"")
    sys.exit(1)

conn_str = sys.argv[1]

DATA_B64 = """"""

raw = gzip.decompress(base64.b64decode(DATA_B64))
text = raw.decode("utf-8")
reader = csv.DictReader(io.StringIO(text))
rows = list(reader)
print(f"Okunan satir sayisi: {len(rows)}")

cols = ["s_no","koy_adi","adi","soyadi","sayac_no","senet_tutari","sayac_tutari",
        "alinan_tutar","malzeme_tutari","malzeme_alinan","senet_no","senet_sahibi_adi",
        "senet_sahibi_soyadi","telefon","baba_adi","montaj_tarihi","odeme_tarihi",
        "odeme_sekli","odemeyi_gonderen","aciklama","muhtara_odenecek","muhtara_odenen","fatura_no"]

numeric_cols = {"s_no","senet_tutari","sayac_tutari","alinan_tutar","malzeme_tutari",
                "malzeme_alinan","muhtara_odenecek","muhtara_odenen"}

def clean(row):
    out = []
    for c in cols:
        v = row.get(c, "")
        if v == "" or v is None:
            out.append(None)
        elif c in numeric_cols:
            try:
                out.append(float(v))
            except ValueError:
                out.append(None)
        else:
            out.append(v)
    return out

conn = psycopg2.connect(conn_str)
cur = conn.cursor()

placeholders = ", ".join(["%s"] * len(cols))
col_list = ", ".join(cols)
sql = f"INSERT INTO abone ({col_list}) VALUES ({placeholders})"

batch = []
inserted = 0
for row in rows:
    batch.append(tuple(clean(row)))
    if len(batch) >= 500:
        cur.executemany(sql, batch)
        conn.commit()
        inserted += len(batch)
        print(f"  {inserted} satir yazildi...")
        batch = []

if batch:
    cur.executemany(sql, batch)
    conn.commit()
    inserted += len(batch)

print(f"TAMAMLANDI: {inserted} satir 'abone' tablosuna eklendi.")
cur.close()
conn.close()
